/** The OpenAITextProviderOptions for each known model ID. */

export type OpenAITextProviderOptionsByModel = OpenAITextProviderOptionsByModelGenerated &
  Omit<Sdk.OpenAIChatModelProviderOptionsByName, keyof OpenAITextProviderOptionsByModelGenerated>;

/**
 * OpenAITextProviderOptions of `@tanstack/ai-openai`, narrowed to the model.
 * Without a model, or with an unknown model ID, it is the original SDK type. A model ID
 * that the SDK knows only for another model type (for example an image model) gives an
 * error type.
 */
export type OpenAITextProviderOptions<
  MODEL extends keyof OpenAITextProviderOptionsByModel | ResponsesModelIds | (string & {}) = string,
> = MODEL extends keyof OpenAITextProviderOptionsByModel
  ? OpenAITextProviderOptionsByModel[MODEL]
  : MODEL extends keyof ResponsesWrongModels
    ? ResponsesWrongModels[MODEL]
    : ResponsesBase;

// Target "chat": OpenAIChatCompletionsProviderOptions (models.dev API "chat-completions").

type ChatBase = Sdk.OpenAIChatCompletionsProviderOptions;

/** The model IDs that the SDK accepts for this target. */
export type ChatModelIds = KnownModelIds<Sdk.OpenAIChatModel>;
/** The model IDs of other model types that this target does not accept. */
type ChatWrongModels = WrongModels<ChatModelIds, OtherModelIds>;

/** The SDK subtype of a model, or the base type for other models. */
type ChatSubType<MODEL extends string> =
  MODEL extends keyof Sdk.OpenAIChatModelProviderOptionsByName
    ? Sdk.OpenAIChatModelProviderOptionsByName[MODEL]
    : ChatBase;

