/** The OpenAIChatCompletionsProviderOptions for each known model ID. */

export type OpenAIChatCompletionsProviderOptionsByModel =
  OpenAIChatCompletionsProviderOptionsByModelGenerated &
    Omit<
      Sdk.OpenAIChatModelProviderOptionsByName,
      keyof OpenAIChatCompletionsProviderOptionsByModelGenerated
    >;

/**
 * OpenAIChatCompletionsProviderOptions of `@tanstack/ai-openai`, narrowed to the model.
 * Without a model, or with an unknown model ID, it is the original SDK type. A model ID
 * that the SDK knows only for another model type (for example an image model) gives an
 * error type.
 */
export type OpenAIChatCompletionsProviderOptions<
  MODEL extends keyof OpenAIChatCompletionsProviderOptionsByModel | ChatModelIds | (string & {}) =
    string,
> = MODEL extends keyof OpenAIChatCompletionsProviderOptionsByModel
  ? OpenAIChatCompletionsProviderOptionsByModel[MODEL]
  : MODEL extends keyof ChatWrongModels
    ? ChatWrongModels[MODEL]
    : ChatBase;

/** The registry entry of this provider. */
export type Provider = {
  optionsKey: never;
  defaultTarget: 'responses';
  targets: {
    responses: {
      base: ResponsesBase;
      byModel: OpenAITextProviderOptionsByModel;
      modelIds: ResponsesModelIds;
      wrongModels: ResponsesWrongModels;
    };
    chat: {
      base: ChatBase;
      byModel: OpenAIChatCompletionsProviderOptionsByModel;
      modelIds: ChatModelIds;
      wrongModels: ChatWrongModels;
    };
  };
};
